cat > c.mjs <<'E'
import { chromium } from 'playwright';
const b=await chromium.launch();const p=await b.newPage();
await p.goto('http://127.0.0.1:65166');
await p.fill('input[type=email],input[name=email]','ops@lab.test');
await p.fill('input[type=password]','lab-ops-pass');
await p.keyboard.press('Enter');
await p.waitForTimeout(1500);
await p.click('text=Customers');await p.waitForTimeout(1000);
await p.locator("tr").nth(2).getByText("Archive").click();
await p.waitForTimeout(500);
await p.getByRole("dialog").locator("input").fill("Berg & Co");
await p.getByRole("button",{name:"Archive customer"}).click();
await p.waitForTimeout(1500);
console.log((await p.innerText("body")).split("\n").filter(l=>!l.includes("\t")).join("\n"));
await b.close();
E
node c.mjs

